    e['src']=dict(author=author,year=str(year),jur=jur,title_latin=tl,sw='',where=where,latin=bool(tl))
    e['links']=[dict(url=u,label=l,site=s,domain=u.split('/')[2]) for u,l,s in links]
    return e
